    scope = "test";
  } else if (files.every((f) => f.startsWith("cli/"))) {
    scope = "cli";
  } else if (files.every((f) => f.startsWith("core/"))) {
export function commitChanges(workspace: string, message: string): { success: boolean; hash?: string; error?: string } {
  try {
